def transform(grid):
    h, w = len(grid), len(grid[0])

    # The separator color is prominent in both complete rows and columns.
    colors = set(v for row in grid for v in row)
    sep = max(
        colors,
        key=lambda c: min(
            max(sum(v == c for v in row) for row in grid),
            max(sum(grid[r][j] == c for r in range(h)) for j in range(w))
        )
    )

    # Find the separator rows and columns.
    row_lines = [r for r in range(h)
                 if sum(v == sep for v in grid[r]) >= 0.6 * w]
    col_lines = [j for j in range(w)
                 if sum(grid[r][j] == sep for r in range(h)) >= 0.6 * h]

    # The most common non-separator color is the tile background.
    counts = {}
    for row in grid:
        for v in row:
            if v != sep:
                counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get)

    # Colored marks at separator intersections define the rectangle to decode.
    marks = {}
    for i, r in enumerate(row_lines):
        for j, c in enumerate(col_lines):
            v = grid[r][c]
            if v != sep and v != background:
                marks[i, j] = v

    if not marks:
        return [[background]]

    r0 = min(i for i, _ in marks)
    r1 = max(i for i, _ in marks)
    c0 = min(j for _, j in marks)
    c1 = max(j for _, j in marks)

    out = []
    for i in range(r0, r1):
        row = []
        for j in range(c0, c1):
            corners = [marks.get((i, j)), marks.get((i + 1, j)),
                       marks.get((i, j + 1)), marks.get((i + 1, j + 1))]
            if corners[0] is not None and all(v == corners[0] for v in corners):
                row.append(corners[0])
            else:
                row.append(background)
        out.append(row)
    return out
